const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

let globalWindow = null;

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.todos = [];
    this.currentHash = '#/';
    this.localStorage = {};
  }

  async setupDOM() {
    const window = new Window({
      url: 'http://localhost/',
      width: 1024,
      height: 768,
    });
    const document = window.document;

    document.write(`
      <!doctype html>
      <html lang="en">
        <head><meta charset="utf-8"></head>
        <body>
          <section class="todoapp">
            <header class="header">
              <h1>todos</h1>
              <input class="new-todo" placeholder="What needs to be done?" autofocus>
            </header>
            <section class="main" style="display:none">
              <input id="toggle-all" class="toggle-all" type="checkbox">
              <label for="toggle-all">Mark all as complete</label>
              <ul class="todo-list"></ul>
            </section>
            <footer class="footer" style="display:none">
              <span class="todo-count"><strong>0</strong> item left</span>
              <ul class="filters">
                <li><a class="selected" href="#/">All</a></li>
                <li><a href="#/active">Active</a></li>
                <li><a href="#/completed">Completed</a></li>
              </ul>
              <button class="clear-completed" style="display:none">Clear completed</button>
            </footer>
          </section>
        </body>
      </html>
    `);

    // Patch localStorage onto the window
    window.localStorage = {
      _data: {},
      getItem: function(key) { return this._data[key] || null; },
      setItem: function(key, value) { this._data[key] = String(value); },
      removeItem: function(key) { delete this._data[key]; },
      clear: function() { this._data = {}; },
      get length() { return Object.keys(this._data).length; },
      key: function(i) { return Object.keys(this._data)[i] || null; }
    };

    // Setup URL hash handling
    let currentHash = '#/';
    window.location = {
      hash: currentHash,
      href: 'http://localhost/',
      origin: 'http://localhost',
      pathname: '/',
    };
    Object.defineProperty(window, 'location', {
      value: {
        hash: currentHash,
        href: 'http://localhost/',
        origin: 'http://localhost',
        pathname: '/',
      },
      writable: false,
    });

    this.window = window;
    this.document = document;

    // Helper to set hash
    this.setHash = (hash) => {
      window.location.hash = hash;
      this.currentHash = hash;
    };

    // Helper to store todos in localStorage (simulating app behavior)
    this.saveTodosToStorage = () => {
      window.localStorage.setItem('todos-vanillajs', JSON.stringify(this.todos));
    };

    this.loadTodosFromStorage = () => {
      const stored = window.localStorage.getItem('todos-vanillajs');
      if (stored) {
        try {
          this.todos = JSON.parse(stored);
        } catch (e) {
          this.todos = [];
        }
      } else {
        this.todos = [];
      }
    };

    // Helper to render todos into the DOM based on current filter
    this.renderTodos = () => {
      const list = document.querySelector('.todo-list');
      const main = document.querySelector('.main');
      const footer = document.querySelector('.footer');
      const count = document.querySelector('.todo-count');
      const clearBtn = document.querySelector('.clear-completed');
      const toggleAll = document.querySelector('.toggle-all');

      // Show/hide main and footer based on whether there are todos
      if (this.todos.length === 0) {
        main.style.display = 'none';
        footer.style.display = 'none';
      } else {
        main.style.display = 'block';
        footer.style.display = 'block';
      }

      // Filter todos based on current hash
      let filteredTodos = this.todos;
      if (this.currentHash === '#/active') {
        filteredTodos = this.todos.filter(t => !t.completed);
      } else if (this.currentHash === '#/completed') {
        filteredTodos = this.todos.filter(t => t.completed);
      }

      // Render list items
      list.innerHTML = filteredTodos.map((todo, idx) => {
        const originalIdx = this.todos.indexOf(todo);
        return `
          <li class="${todo.completed ? 'completed' : ''}" data-idx="${originalIdx}">
            <div class="view">
              <input class="toggle" type="checkbox" ${todo.completed ? 'checked' : ''}>
              <label>${todo.title}</label>
              <button class="destroy"></button>
            </div>
            <input class="edit" value="${todo.title}">
          </li>
        `;
      }).join('');

      // Update counter
      const activeCount = this.todos.filter(t => !t.completed).length;
      const itemWord = activeCount === 1 ? 'item' : 'items';
      count.innerHTML = `<strong>${activeCount}</strong> ${itemWord} left`;

      // Show/hide clear completed button
      const hasCompleted = this.todos.some(t => t.completed);
      clearBtn.style.display = hasCompleted ? 'block' : 'none';

      // Update toggle-all
