const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
    this.todos = [];
    this.currentHash = '#/';
  }

  async setupDOM() {
    const window = new Window({
      url: 'http://localhost/',
      width: 1024,
      height: 768,
    });
    const document = window.document;

    document.write(`
      <!doctype html>
      <html lang="en">
        <head><meta charset="utf-8"></head>
        <body>
          <section class="todoapp">
            <header class="header">
              <h1>todos</h1>
              <input class="new-todo" placeholder="What needs to be done?" autofocus>
            </header>
            <section class="main" style="display:none">
              <input id="toggle-all" class="toggle-all" type="checkbox">
              <label for="toggle-all">Mark all as complete</label>
              <ul class="todo-list"></ul>
            </section>
            <footer class="footer" style="display:none">
              <span class="todo-count"><strong>0</strong> item left</span>
              <ul class="filters">
                <li><a class="selected" href="#/">All</a></li>
                <li><a href="#/active">Active</a></li>
                <li><a href="#/completed">Completed</a></li>
              </ul>
              <button class="clear-completed" style="display:none">Clear completed</button>
            </footer>
          </section>
        </body>
      </html>
    `);

    this.window = window;
    this.document = document;
  }

  saveTodosToStorage() {
    this.window.localStorage.setItem('todos-vanillajs', JSON.stringify(this.todos));
  }

  loadTodosFromStorage() {
    const stored = this.window.localStorage.getItem('todos-vanillajs');
    if (stored) {
      try {
        this.todos = JSON.parse(stored);
      } catch (e) {
        this.todos = [];
      }
    } else {
      this.todos = [];
    }
  }

  renderTodos() {
    const list = this.document.querySelector('.todo-list');
    const main = this.document.querySelector('.main');
    const footer = this.document.querySelector('.footer');
    const count = this.document.querySelector('.todo-count');
    const clearBtn = this.document.querySelector('.clear-completed');
    const toggleAll = this.document.querySelector('.toggle-all');

    // Show/hide main and footer based on todo count
    if (this.todos.length === 0) {
      main.style.display = 'none';
      footer.style.display = 'none';
    } else {
      main.style.display = 'block';
      footer.style.display = 'block';
    }

    // Filter based on current hash
    let filteredTodos = this.todos;
    if (this.currentHash === '#/active') {
      filteredTodos = this.todos.filter(t => !t.completed);
    } else if (this.currentHash === '#/completed') {
      filteredTodos = this.todos.filter(t => t.completed);
    }

    // Render list items
    list.innerHTML = filteredTodos.map((todo, idx) => {
      const originalIdx = this.todos.indexOf(todo);
      return `
          <li class="${todo.completed ? 'completed' : ''}" data-idx="${originalIdx}">
            <div class="view">
              <input class="toggle" type="checkbox" ${todo.completed ? 'checked' : ''}>
              <label>${todo.title}</label>
              <button class="destroy"></button>
            </div>
            <input class="edit" value="${todo.title}">
          </li>
        `;
    }).join('');

    // Update counter
    const activeCount = this.todos.filter(t => !t.completed).length;
    const itemWord = activeCount === 1 ? 'item' : 'items';
    count.innerHTML = `<strong>${activeCount}</strong> ${itemWord} left`;

    // Show/hide clear completed button
    const hasCompleted = this.todos.some(t => t.completed);
    clearBtn.style.display = hasCompleted ? 'block' : 'none';

    // Update toggle-all
    const allCompleted = this.todos.length > 0 && this.todos.every(t => t.completed);
    toggleAll.checked = allCompleted;

    // Update filter links
    this.document.querySelectorAll('.filters a').forEach(a => {
      const href = a.getAttribute('href');
      a.classList.toggle('selected', href === this.currentHash);
    });
  }

  async resetState() {
    this.todos = [];
    this.currentHash = '#/';
    if (this.window) {
      this.window.localStorage.clear();
      this.window.close();
    }
    await this.setupDOM();
  }
}

setWorldConstructor(TodoWorld);

Before(async function () {
  await this.setupDOM();
});

After(async function () {
  if (this.window) {
    this.window.close();
  }
});

const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

class TodoWorld {
  constructor() {
    this.window = null;
    this.document = null;
  }

  async setupDOM() {
    const window = new Window({
      url: 'http://localhost/',
      width: 1024,
      height: 768,
    });
    const document = window.document;

    document.write(`
      <!doctype html>
      <html lang="en">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>TodoMVC</title>
        </head>
        <body>
          <section class="todoapp">
            <header class="header">
              <h1>todos</h1>
              <input class="new-todo" placeholder="What needs to be done?" autofocus>
            </header>
            <section class="main">
              <input id="toggle-all" class="toggle-all" type="checkbox">
              <label for="toggle-all">Mark all as complete</label>
              <ul class="todo-list"></ul>
            </section>
            <footer class="footer">
              <span class="todo-count"><strong>0</strong> item left</span>
              <ul class="filters">
                <li><a class="selected" href="#/">All</a></li>
                <li><a href="#/active">Active</a></li>
                <li><a href="#/completed">Completed</a></li>
              </ul>
              <button class="clear-completed">Clear completed</button>
            </footer>
          </section>
          <script src="js/app.js"></script>
        </body>
      </html>
    `);

    this.window = window;
    this.document = document;
  }

  async resetState() {
    if (this.window) {
      this.window.localStorage.clear();
      this.window.close();
    }
    await this.setupDOM();
  }

  // Simulate typing into an input element
  typeInto(element, text) {
    element.value = text;
    element.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  }

  // Simulate pressing a key on an element
  pressKey(element, key) {
    const event = new this.window.KeyboardEvent('keydown', {
      key: key,
      keyCode: key === 'Enter' ? 13 : key === 'Escape' ? 27 : 0,
      bubbles: true,
    });
    element.dispatchEvent(event);
  }

  // Simulate click on an element
  click(element) {
    element.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  // Simulate double-click
  doubleClick(element) {
    element.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  // Find a todo list item by its label text
  findTodoLi(title) {
    const labels = this.document.querySelectorAll('.todo-list li .view label');
    for (const label of labels) {
      if (label.textContent.trim() === title) {
        return label.closest('li');
      }
    }
    return null;
  }
}

setWorldConstructor(TodoWorld);

