(function () {
  'use strict';

  var ENTER_KEY = 13;

  var todoList = document.querySelector('.todo-list');
  var newTodoInput = document.querySelector('.new-todo');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');

  var todos = [];

  function render() {
    todoList.innerHTML = '';
    todos.forEach(function (todo, index) {
      var li = document.createElement('li');
      li.dataset.idx = index;
      if (todo.completed) {
        li.className = 'completed';
      }
      li.innerHTML = '<div class="view">' +
        '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
        '<label>' + todo.title + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + todo.title + '">';
      todoList.appendChild(li);
    });

    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = 'block';
      footer.style.display = 'block';
    }

    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    document.querySelector('.toggle-all').checked = allCompleted;

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var count = document.querySelector('.todo-count');
    count.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

    var clearBtn = document.querySelector('.clear-completed');
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearBtn.style.display = hasCompleted ? 'block' : 'none';
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (trimmed === '') {
      return;
    }
    todos.push({ id: Date.now(), title: trimmed, completed: false });
    newTodoInput.value = '';
    render();
  }

  newTodoInput.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      addTodo(newTodoInput.value);
    }
  });

  todoList.addEventListener('click', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (!li) { return; }
    var idx = parseInt(li.dataset.idx, 10);
    if (isNaN(idx) || !todos[idx]) { return; }

    if (target.classList.contains('toggle')) {
      todos[idx].completed = !todos[idx].completed;
      render();
    } else if (target.classList.contains('destroy')) {
      todos.splice(idx, 1);
      render();
    }
  });

  // Show destroy button on hover via mouseenter delegation
  todoList.addEventListener('mouseenter', function (e) {
    var target = e.target;
    var li = target.closest('li');
    if (li) {
      var btn = li.querySelector('.destroy');
      if (btn) { btn.style.display = 'block'; }
    }
  }, true);

  var toggleAll = document.querySelector('.toggle-all');
  document.querySelector('.clear-completed').addEventListener('click', function () {
    todos = todos.filter(function (t) { return !t.completed; });
    render();
  });

  toggleAll.addEventListener('click', function () {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    render();
  });

  render();
})();

