  // Editing: double-click on label
  todoList.addEventListener('dblclick', function (e) {
    var target = e.target;
    if (target.tagName === 'LABEL') {
      var li = target.closest('li');
      if (li) {
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.value = editInput.value; // position cursor at end
      }
    }
  });

  // Editing: save on Enter, cancel on Escape
  todoList.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY || e.keyCode === 27) {
      var li = e.target.closest('li');
      if (!li || !li.classList.contains('editing')) { return; }
      var idx = parseInt(li.dataset.idx, 10);
      if (isNaN(idx) || !todos[idx]) { return; }

      if (e.keyCode === ENTER_KEY) {
        var newTitle = li.querySelector('.edit').value.trim();
        if (newTitle === '') {
          todos.splice(idx, 1);
        } else {
          todos[idx].title = newTitle;
        }
      }
      // Escape just discards - revert by rerendering without changes
      render();
    }
  });

  // Editing: save on blur
  todoList.addEventListener('focusout', function (e) {
    var editInput = e.target;
    if (!editInput.classList.contains('edit')) { return; }
    var li = editInput.closest('li');
    if (!li || !li.classList.contains('editing')) { return; }
    var idx = parseInt(li.dataset.idx, 10);
    if (isNaN(idx) || !todos[idx]) { return; }

    var newTitle = editInput.value.trim();
    if (newTitle === '') {
      todos.splice(idx, 1);
    } else {
      todos[idx].title = newTitle;
    }
    render();
  });

  render();
